import "jsr:@supabase/functions-js/edge-runtime.d.ts";

const PROJECT_URL = Deno.env.get("SUPABASE_URL")!;
const ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
const SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const MCP_URL = `${PROJECT_URL}/functions/v1/lef-assistant-mcp`;
const AUTH_SERVER = `${PROJECT_URL}/auth/v1`;
const cors = { "access-control-allow-origin": "*", "access-control-allow-headers": "authorization, content-type, mcp-protocol-version, mcp-session-id", "access-control-allow-methods": "GET, POST, OPTIONS" };

function json(body: unknown, status = 200, extra: Record<string, string> = {}) { return new Response(JSON.stringify(body), { status, headers: { ...cors, "content-type": "application/json", ...extra } }); }
function rpcResult(id: unknown, value: unknown) { return json({ jsonrpc: "2.0", id, result: value }); }
function rpcError(id: unknown, code: number, message: string) { return json({ jsonrpc: "2.0", id, error: { code, message } }); }
function toolText(data: unknown, isError = false) { return { content: [{ type: "text", text: JSON.stringify(data, null, 2) }], isError }; }
function oauthChallenge() { return json({ error: "authentication_required" }, 401, { "www-authenticate": `Bearer resource_metadata="${MCP_URL}/.well-known/oauth-protected-resource"` }); }

async function db(path: string, init: RequestInit = {}) {
  const response = await fetch(`${PROJECT_URL}/rest/v1/${path}`, { ...init, headers: { apikey: SERVICE_KEY, authorization: `Bearer ${SERVICE_KEY}`, "content-type": "application/json", ...(init.headers || {}) } });
  const body = await response.text();
  if (!response.ok) throw new Error(`database request failed (${response.status}): ${body.slice(0, 500)}`);
  return body ? JSON.parse(body) : null;
}

async function authenticate(req: Request) {
  const auth = req.headers.get("authorization") || "";
  if (!auth.toLowerCase().startsWith("bearer ")) return null;
  const response = await fetch(`${PROJECT_URL}/auth/v1/user`, { headers: { apikey: ANON_KEY, authorization: `Bearer ${auth.slice(7)}` } });
  if (!response.ok) return null;
  const user = await response.json();
  return { id: user.id as string, email: user.email as string };
}

const enc = (value: unknown) => encodeURIComponent(String(value));
function confirmed(args: any) { if (args?.confirmed !== true) throw new Error("explicit user confirmation is required"); }
function uuid(value: unknown, field: string) { if (typeof value !== "string" || !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value)) throw new Error(`${field} must be a UUID`); return value; }
function txt(value: unknown, field: string, max: number, required = false) { if (value == null && !required) return null; if (typeof value !== "string" || (required && !value.trim())) throw new Error(`${field} is invalid`); const result = value.trim(); if (result.length > max) throw new Error(`${field} is too long`); return result || null; }
function choice(value: unknown, field: string, values: string[]) { if (typeof value !== "string" || !values.includes(value)) throw new Error(`${field} must be one of: ${values.join(", ")}`); return value; }
function instant(value: unknown, field: string) { if (value == null) return null; if (typeof value !== "string" || Number.isNaN(Date.parse(value))) throw new Error(`${field} must be an ISO timestamp`); return new Date(value).toISOString(); }
function date(value: unknown, field: string) { if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) throw new Error(`${field} must be YYYY-MM-DD`); const d = new Date(`${value}T12:00:00Z`); if (Number.isNaN(d.valueOf()) || d.getUTCDay() !== 1) throw new Error(`${field} must be a Monday`); return value; }
function number(value: unknown, field: string, nullable = false) { if (value == null && nullable) return null; const result = Number(value); if (!Number.isFinite(result) || result < 0) throw new Error(`${field} must be a non-negative number`); return result; }
function confidence(value: unknown) { if (value == null) return null; const result = Number(value); if (!Number.isFinite(result) || result < 0 || result > 1) throw new Error("confidence must be between 0 and 1"); return result; }
function object(value: unknown, field: string) { if (value == null) return {}; if (typeof value !== "object" || Array.isArray(value)) throw new Error(`${field} must be an object`); return value; }
function limit(value: unknown) { return Math.min(Math.max(Number(value || 50), 1), 100); }
function localDate(value: unknown, field: string) { if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) throw new Error(`${field} must be YYYY-MM-DD`); const parsed = new Date(`${value}T12:00:00Z`); if (Number.isNaN(parsed.valueOf()) || parsed.toISOString().slice(0, 10) !== value) throw new Error(`${field} is not a valid date`); return value; }
function timezone(value: unknown) { const result = txt(value, "timezone", 100) || "America/Sao_Paulo"; try { new Intl.DateTimeFormat("en-CA", { timeZone: result }).format(new Date()); } catch { throw new Error("timezone must be a valid IANA timezone"); } return result; }
function addDays(value: string, amount: number) { const parsed = new Date(`${value}T12:00:00Z`); parsed.setUTCDate(parsed.getUTCDate() + amount); return parsed.toISOString().slice(0, 10); }
function instantLocalDay(value: unknown, zone: string) { if (typeof value !== "string" || Number.isNaN(Date.parse(value))) return null; const parts = new Intl.DateTimeFormat("en-CA", { timeZone: zone, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date(value)); const part = (type: string) => parts.find((item) => item.type === type)?.value || ""; return `${part("year")}-${part("month")}-${part("day")}`; }
const checkInTypes = ["morning_plan","midday_review","proactive_intervention","end_of_day","project","weekly_sales","weekly_workspace","weekend_review","workspace_review","conversation","administration_weekly","administration_monthly","other"];
const digestFields = ["outcomes","intentions","decisions","blockers","priority_changes","unresolved_questions","follow_ups","evidence_refs"];
function hasForbiddenDigestKey(value: unknown): boolean { if (!value || typeof value !== "object") return false; if (Array.isArray(value)) return value.some(hasForbiddenDigestKey); return Object.entries(value).some(([key, nested]) => ["transcript","messages","raw_messages","verbatim_transcript"].includes(key.toLowerCase()) || hasForbiddenDigestKey(nested)); }
function reviewDigest(value: unknown) {
  const source: any = object(value, "digest");
  const unexpected=Object.keys(source).filter((key)=>key!=="schema_version"&&!digestFields.includes(key));
  if(unexpected.length)throw new Error(`digest contains unsupported fields: ${unexpected.join(", ")}`);
  if(hasForbiddenDigestKey(source))throw new Error("digest must not contain a transcript or raw messages");
  const result: any = { schema_version: 1 };
  for (const field of digestFields) {
    const items = source[field] == null ? [] : source[field];
    if (!Array.isArray(items) || items.length > 50) throw new Error(`digest.${field} must be an array with at most 50 items`);
    for (const item of items) if ((typeof item !== "string" && (typeof item !== "object" || item == null || Array.isArray(item))) || JSON.stringify(item).length > 5000) throw new Error(`digest.${field} contains an invalid or oversized item`);
    result[field] = items;
  }
  if (JSON.stringify(result).length > 50000) throw new Error("digest is too large");
  return result;
}

async function own(table: string, userId: string, value: unknown, field: string) { const id = uuid(value, field); const rows = await db(`${table}?id=eq.${id}&owner_user_id=eq.${userId}&select=*`); if (!rows.length) throw new Error(`${field.replace("_id", "")} was not found`); return rows[0]; }
async function insert(table: string, body: unknown) { const rows = await db(`${table}?select=*`, { method: "POST", headers: { Prefer: "return=representation" }, body: JSON.stringify(body) }); return rows[0]; }
async function patch(table: string, userId: string, id: string, body: unknown) { const rows = await db(`${table}?id=eq.${id}&owner_user_id=eq.${userId}&select=*`, { method: "PATCH", headers: { Prefer: "return=representation" }, body: JSON.stringify(body) }); return rows[0]; }

async function listMemories(args: any, userId: string) { let path = `assistant_memories?owner_user_id=eq.${userId}&select=*&order=learned_at.desc&limit=${limit(args.limit)}`; if (!args.include_expired) path += `&or=(expires_at.is.null,expires_at.gt.${enc(new Date().toISOString())})`; if (args.memory_type) path += `&memory_type=eq.${choice(args.memory_type, "memory_type", ["preference","priority","routine","work_pattern","context","decision","other"])}`; return { memories: await db(path) }; }
async function recordMemory(args: any, userId: string) {
  const sensitivity = args.sensitivity ? choice(args.sensitivity, "sensitivity", ["normal","sensitive"]) : "normal";
  const confirmationState = args.confirmation_state ? choice(args.confirmation_state, "confirmation_state", ["inferred","confirmed"]) : "inferred";
  if (sensitivity === "sensitive" || confirmationState === "confirmed" || args.source_domain !== "conversation") confirmed(args);
  const sourceDomain = args.source_domain ? choice(args.source_domain, "source_domain", ["assistant","crm","projects","administration","outlook_calendar","outlook_mail","reminders","conversation","other"]) : "conversation";
  const sourceType = txt(args.source_record_type, "source_record_type", 200);
  const sourceId = txt(args.source_external_id, "source_external_id", 500);
  if (sourceId) { const prior = await db(`assistant_memories?owner_user_id=eq.${userId}&source_domain=eq.${sourceDomain}&source_record_type=${sourceType ? `eq.${enc(sourceType)}` : "is.null"}&source_external_id=eq.${enc(sourceId)}&select=*`); if (prior.length) return { memory: prior[0], reused: true }; }
  const memory = await insert("assistant_memories", { owner_user_id: userId, memory_type: choice(args.memory_type, "memory_type", ["preference","priority","routine","work_pattern","context","decision","other"]), content: txt(args.content, "content", 10000, true), confirmation_state: confirmationState, sensitivity, source_domain: sourceDomain, source_record_type: sourceType, source_external_id: sourceId, source_url: txt(args.source_url, "source_url", 2000), confidence: confidence(args.confidence), expires_at: instant(args.expires_at, "expires_at"), context: object(args.context, "context") });
  return { memory, notice: "Recorded Assistant memory can be corrected, expired, or removed." };
}
async function updateMemory(args: any, userId: string) { confirmed(args); const row = await own("assistant_memories", userId, args.memory_id, "memory_id"); const u: any = { corrected_at: new Date().toISOString() }; if (Object.hasOwn(args,"content")) u.content=txt(args.content,"content",10000,true); if(Object.hasOwn(args,"confirmation_state"))u.confirmation_state=choice(args.confirmation_state,"confirmation_state",["inferred","confirmed"]); if(Object.hasOwn(args,"sensitivity"))u.sensitivity=choice(args.sensitivity,"sensitivity",["normal","sensitive"]); if(Object.hasOwn(args,"confidence"))u.confidence=confidence(args.confidence); if(Object.hasOwn(args,"expires_at"))u.expires_at=instant(args.expires_at,"expires_at"); return { memory: await patch("assistant_memories",userId,row.id,u) }; }
async function deleteMemory(args:any,userId:string){confirmed(args);const row=await own("assistant_memories",userId,args.memory_id,"memory_id");await db(`assistant_memories?id=eq.${row.id}&owner_user_id=eq.${userId}`,{method:"DELETE"});return{deleted:true,memory_id:row.id};}

async function listCheckIns(args:any,userId:string){let path=`assistant_check_ins?owner_user_id=eq.${userId}&select=*&order=scheduled_at.desc.nullslast,created_at.desc&limit=${limit(args.limit)}`;if(args.status)path+=`&status=eq.${choice(args.status,"status",["planned","in_progress","completed","cancelled","rescheduled"])}`;if(args.check_in_type)path+=`&check_in_type=eq.${choice(args.check_in_type,"check_in_type",checkInTypes)}`;if(args.local_day_from)path+=`&local_day=gte.${localDate(args.local_day_from,"local_day_from")}`;if(args.local_day_to)path+=`&local_day=lte.${localDate(args.local_day_to,"local_day_to")}`;return{check_ins:await db(path)};}
async function createCheckIn(args:any,userId:string){if(args.source_external_id==null||args.confirmed===true){if(args.confirmed===true)confirmed(args);}const body:any={owner_user_id:userId,check_in_type:choice(args.check_in_type,"check_in_type",checkInTypes),status:"planned",scheduled_at:instant(args.scheduled_at,"scheduled_at"),reason:txt(args.reason,"reason",2000),source_external_id:txt(args.source_external_id,"source_external_id",500),context:object(args.context,"context")};if(args.local_day)body.local_day=localDate(args.local_day,"local_day");if(args.timezone)body.timezone=timezone(args.timezone);return{check_in:await insert("assistant_check_ins",body)};}
async function updateCheckIn(args:any,userId:string){confirmed(args);const row=await own("assistant_check_ins",userId,args.check_in_id,"check_in_id");const u:any={};if(Object.hasOwn(args,"status")){u.status=choice(args.status,"status",["planned","in_progress","completed","cancelled","rescheduled"]);u.completed_at=u.status==="completed"?new Date().toISOString():null;if(u.status==="in_progress"&&!row.started_at)u.started_at=new Date().toISOString();}if(Object.hasOwn(args,"scheduled_at"))u.scheduled_at=instant(args.scheduled_at,"scheduled_at");if(Object.hasOwn(args,"reason"))u.reason=txt(args.reason,"reason",2000);if(Object.hasOwn(args,"summary"))u.summary=txt(args.summary,"summary",10000);if(Object.hasOwn(args,"rescheduled_to_id"))u.rescheduled_to_id=args.rescheduled_to_id?uuid(args.rescheduled_to_id,"rescheduled_to_id"):null;if(!Object.keys(u).length)throw new Error("no supported changes were supplied");return{check_in:await patch("assistant_check_ins",userId,row.id,u)};}

async function getReviewContinuity(args:any,userId:string){
  const scope=choice(args.scope,"scope",["daily","weekly"]);
  const zone=timezone(args.timezone);
  const start=scope==="weekly"?date(args.week_start,"week_start"):localDate(args.local_day,"local_day");
  const end=scope==="weekly"?addDays(start,6):start;
  const checkIns=await db(`assistant_check_ins?owner_user_id=eq.${userId}&local_day=gte.${start}&local_day=lte.${end}&select=*&order=local_day.asc,created_at.asc&limit=100`);
  const allCommitments=await db(`assistant_commitments?owner_user_id=eq.${userId}&select=*&order=created_at.desc&limit=100`);
  const checkInIds=new Set(checkIns.map((row:any)=>row.id));
  const periodCommitments=allCommitments.filter((row:any)=>checkInIds.has(row.check_in_id)||((instantLocalDay(row.created_at,zone)||"")>=start&&(instantLocalDay(row.created_at,zone)||"")<=end));
  const openCarryOver=allCommitments.filter((row:any)=>row.status==="confirmed"&&!periodCommitments.some((item:any)=>item.id===row.id));
  const interventions=await db(`assistant_interventions?owner_user_id=eq.${userId}&local_day=gte.${start}&local_day=lte.${end}&select=*&order=created_at.asc&limit=100`);
  const weekly=scope==="weekly"?await getWeeklyReview({week_start:start},userId):null;
  return{scope,timezone:zone,period:{start,end},check_ins:checkIns,period_commitments:periodCommitments,open_carry_over_commitments:openCarryOver,interventions,weekly_review:weekly,truncated:{check_ins:checkIns.length===100,commitments:allCommitments.length===100,interventions:interventions.length===100},domain_refresh_required:["reminders","projects","crm","administration","outlook_calendar","outlook_mail"],notice:"Review digests provide conversational continuity only. Refresh authoritative domains before advising or changing work."};
}
async function startReviewSession(args:any,userId:string){
  const type=choice(args.review_type,"review_type",["morning_plan","midday_review","end_of_day","weekly_sales","weekly_workspace","weekend_review","workspace_review","conversation"]);
  const key=txt(args.session_key,"session_key",500,true)!;
  const day=localDate(args.local_day,"local_day");
  const zone=timezone(args.timezone);
  let rows=await db(`assistant_check_ins?owner_user_id=eq.${userId}&check_in_type=eq.${type}&source_external_id=eq.${enc(key)}&select=*`);
  let reused=rows.length>0;
  if(!reused){try{rows=[await insert("assistant_check_ins",{owner_user_id:userId,check_in_type:type,status:"in_progress",scheduled_at:instant(args.scheduled_at,"scheduled_at"),started_at:new Date().toISOString(),reason:txt(args.reason,"reason",2000),source_external_id:key,local_day:day,timezone:zone,context:{...object(args.context,"context"),digest_schema_version:1,source_client:txt(args.source_client,"source_client",100)}})];}catch(error){rows=await db(`assistant_check_ins?owner_user_id=eq.${userId}&check_in_type=eq.${type}&source_external_id=eq.${enc(key)}&select=*`);if(!rows.length)throw error;reused=true;}}
  return{check_in:rows[0],reused,continuity:await getReviewContinuity({scope:"daily",local_day:day,timezone:zone},userId)};
}
async function saveReviewDigest(args:any,userId:string){
  const row=await own("assistant_check_ins",userId,args.check_in_id,"check_in_id");
  if(["cancelled","rescheduled"].includes(row.status))throw new Error("a cancelled or rescheduled review cannot receive a digest");
  const sensitivity=args.sensitivity?choice(args.sensitivity,"sensitivity",["normal","sensitive"]):"normal";
  if(sensitivity==="sensitive")confirmed(args);
  const digest=reviewDigest(args.digest);
  const now=new Date().toISOString();
  const context={...object(row.context,"stored context"),review_digest:digest,digest_sensitivity:sensitivity};
  const updated=await patch("assistant_check_ins",userId,row.id,{status:row.status==="planned"?"in_progress":row.status,started_at:row.started_at||now,summary:txt(args.summary,"summary",10000,true),digest_version:1,last_summarized_at:now,context});
  return{check_in:updated,notice:"Saved a structured, correctable review digest. No transcript or domain record was copied."};
}
async function finalizeReviewSession(args:any,userId:string){confirmed(args);const row=await own("assistant_check_ins",userId,args.check_in_id,"check_in_id");if(["cancelled","rescheduled"].includes(row.status))throw new Error("a cancelled or rescheduled review cannot be finalized");const sensitivity=args.sensitivity?choice(args.sensitivity,"sensitivity",["normal","sensitive"]):"normal";const digest=reviewDigest(args.digest);const now=new Date().toISOString();const context={...object(row.context,"stored context"),review_digest:digest,digest_sensitivity:sensitivity};return{check_in:await patch("assistant_check_ins",userId,row.id,{status:"completed",started_at:row.started_at||now,completed_at:now,summary:txt(args.summary,"summary",10000,true),digest_version:1,last_summarized_at:now,context}),notice:"Finalized the review session. Domain records remain authoritative and unchanged."};}

