const attentionTriggerTypes=["event","periodic","morning_plan","end_of_day","weekly_sales","manual"];
const attentionDecisions=["no_action","pending_delivery","suppressed","failed"];
const interventionStatuses=["pending","delivered","acknowledged","completed","scheduled","snoozed","blocked","rejected","failed","cancelled"];
const authorityDomains=["assistant","crm","projects","administration","outlook_calendar","outlook_mail","reminders","other"];

async function recordAttentionEvaluation(args:any,userId:string){
  const triggerKey=txt(args.trigger_key,"trigger_key",500,true)!;
  const prior=await db(`assistant_attention_evaluations?owner_user_id=eq.${userId}&trigger_key=eq.${enc(triggerKey)}&select=*`);
  if(prior.length)return{evaluation:prior[0],reused:true};
  const evaluation=await insert("assistant_attention_evaluations",{owner_user_id:userId,trigger_type:choice(args.trigger_type,"trigger_type",attentionTriggerTypes),trigger_key:triggerKey,evaluated_at:instant(args.evaluated_at,"evaluated_at")||new Date().toISOString(),window_start:instant(args.window_start,"window_start"),window_end:instant(args.window_end,"window_end"),timezone:txt(args.timezone,"timezone",100)||"America/Sao_Paulo",decision:choice(args.decision,"decision",attentionDecisions),reason:txt(args.reason,"reason",4000),evidence_quality:args.evidence_quality?choice(args.evidence_quality,"evidence_quality",["unknown","partial","verified"]):"unknown",context:object(args.context,"context")});
  return{evaluation,reused:false};
}

async function createIntervention(args:any,userId:string){
  const transactionKey=txt(args.transaction_key,"transaction_key",500,true)!;
  const prior=await db(`assistant_interventions?owner_user_id=eq.${userId}&transaction_key=eq.${enc(transactionKey)}&select=*`);
  if(prior.length)return{intervention:prior[0],reused:true};
  const evaluation=await own("assistant_attention_evaluations",userId,args.evaluation_id,"evaluation_id");
  const checkInId=args.check_in_id?uuid(args.check_in_id,"check_in_id"):null;
  if(checkInId)await own("assistant_check_ins",userId,checkInId,"check_in_id");
  if(!/^\d{4}-\d{2}-\d{2}$/.test(String(args.local_day||"")))throw new Error("local_day must be YYYY-MM-DD");
  const items=Array.isArray(args.items)?args.items:[];
  if(items.length<1||items.length>20)throw new Error("items must contain between 1 and 20 referenced items");
  const intervention=await insert("assistant_interventions",{owner_user_id:userId,evaluation_id:evaluation.id,check_in_id:checkInId,transaction_key:transactionKey,title:txt(args.title,"title",500,true),reason:txt(args.reason,"reason",4000,true),suggested_next_step:txt(args.suggested_next_step,"suggested_next_step",4000),urgency:args.urgency?choice(args.urgency,"urgency",["low","normal","high","urgent"]):"normal",tone_level:args.tone_level?choice(args.tone_level,"tone_level",["helpful","direct","confronting"]):"helpful",status:"pending",not_before:instant(args.not_before,"not_before"),expires_at:instant(args.expires_at,"expires_at"),next_review_at:instant(args.next_review_at,"next_review_at"),local_day:String(args.local_day),daily_sequence:Math.min(Math.max(Number(args.daily_sequence||1),1),99),exception_reason:txt(args.exception_reason,"exception_reason",4000),context:object(args.context,"context")});
  try{
    const rows=items.map((item:any,index:number)=>({owner_user_id:userId,intervention_id:intervention.id,authority_domain:choice(item.authority_domain,`items[${index}].authority_domain`,authorityDomains),source_record_type:txt(item.source_record_type,`items[${index}].source_record_type`,200,true),source_external_id:txt(item.source_external_id,`items[${index}].source_external_id`,500,true),title:txt(item.title,`items[${index}].title`,500,true),summary:txt(item.summary,`items[${index}].summary`,4000),due_at:instant(item.due_at,`items[${index}].due_at`),importance_rank:Math.min(Math.max(Number(item.importance_rank||50),1),100),context:object(item.context,`items[${index}].context`)}));
    await db("assistant_intervention_items",{method:"POST",body:JSON.stringify(rows)});
    await insert("assistant_intervention_events",{owner_user_id:userId,intervention_id:intervention.id,event_type:"created",actor_type:"assistant",details:{trigger_type:evaluation.trigger_type}});
    return{intervention,items:rows,reused:false};
  }catch(error){await db(`assistant_interventions?id=eq.${intervention.id}&owner_user_id=eq.${userId}`,{method:"DELETE"});throw error;}
}

async function listInterventions(args:any,userId:string){
  let path=`assistant_interventions?owner_user_id=eq.${userId}&select=*&order=created_at.desc&limit=${limit(args.limit)}`;
  if(args.status)path+=`&status=eq.${choice(args.status,"status",interventionStatuses)}`;
  const interventions=await db(path);
  if(!interventions.length)return{interventions:[]};
  const ids=interventions.map((row:any)=>row.id).join(",");
  const [items,events]=await Promise.all([db(`assistant_intervention_items?owner_user_id=eq.${userId}&intervention_id=in.(${ids})&select=*&order=importance_rank.asc`),db(`assistant_intervention_events?owner_user_id=eq.${userId}&intervention_id=in.(${ids})&select=*&order=occurred_at.asc`)]);
  return{interventions:interventions.map((row:any)=>({...row,items:items.filter((item:any)=>item.intervention_id===row.id),events:events.filter((event:any)=>event.intervention_id===row.id)}))};
}

async function recordDelivery(args:any,userId:string){
  const intervention=await own("assistant_interventions",userId,args.intervention_id,"intervention_id");
  const result=choice(args.delivery_result,"delivery_result",["delivered","failed","suppressed"]);
  const status=result==="delivered"?"delivered":result==="failed"?"failed":"pending";
  const now=new Date().toISOString();
  const updated=await patch("assistant_interventions",userId,intervention.id,{status,delivered_at:result==="delivered"?now:null,next_review_at:instant(args.next_review_at,"next_review_at"),outcome_note:txt(args.note,"note",4000)});
  await insert("assistant_intervention_events",{owner_user_id:userId,intervention_id:intervention.id,event_type:result==="delivered"?"delivered":result==="failed"?"delivery_failed":"suppressed",actor_type:"system",details:{channel:txt(args.channel,"channel",100)||"chatgpt",reason:txt(args.reason,"reason",2000)}});
  return{intervention:updated};
}

async function recordInterventionOutcome(args:any,userId:string){
  confirmed(args);
  const intervention=await own("assistant_interventions",userId,args.intervention_id,"intervention_id");
  const outcome=choice(args.outcome,"outcome",["acknowledged","completed","scheduled","snoozed","blocked","rejected"]);
  const updated=await patch("assistant_interventions",userId,intervention.id,{status:outcome,next_review_at:instant(args.next_review_at,"next_review_at"),outcome_note:txt(args.note,"note",4000)});
  await insert("assistant_intervention_events",{owner_user_id:userId,intervention_id:intervention.id,event_type:outcome,actor_type:"user",details:{note:txt(args.note,"note",4000),scheduled_for:instant(args.scheduled_for,"scheduled_for"),next_review_at:instant(args.next_review_at,"next_review_at")}});
  return{intervention:updated};
}

